mapper.select:
SELECT p.id, p.name, p.subtitle, p.cover_img AS coverImg, p.sale_type AS saleType, p.is_near_expiry AS isNearExpiry, p.sales, b.name AS brandName, c.name AS categoryName, AS minPrice FROM tb_product p LEFT JOIN tb_brand b ON b.id = p.brand_id AND b.deleted = 0 LEFT JOIN tb_category c ON c.id = p.category_id AND c.deleted = 0
p.deleted = 0 AND p.shelf_status = 1
AND ( p.name LIKE CONCAT('%', #{q.keyword}, '%') OR p.subtitle LIKE CONCAT('%', #{q.keyword}, '%') OR b.name LIKE CONCAT('%', #{q.keyword}, '%') OR c.name LIKE CONCAT('%', #{q.keyword}, '%') )
AND (p.category_id = #{q.categoryId} OR p.category_id IN (SELECT id FROM tb_category WHERE parent_id = #{q.categoryId}))
AND p.brand_id = #{q.brandId}
AND p.sale_type = #{q.saleType}
AND (p.pet_type = #{q.petType} OR p.pet_type = 0)
AND p.is_near_expiry = #{q.isNearExpiry}
AND >= #{q.priceMin}
AND <= #{q.priceMax}
ORDER BY
p.sales DESC minPrice ASC minPrice DESC p.create_time DESC p.create_time DESC
